import json

# Load the full JSON and check pages more carefully
with open('/app/resources/treasury_bulletin_1990_09.json', 'r') as f:
    data = json.load(f)

# Let's look at page_ids
doc = data.get('document', {})
elements = doc.get('elements', [])

# Get elements with page_id info
page_ids = {}
for i, el in enumerate(elements):
    if isinstance(el, dict):
        bbox = el.get('bbox', [])
        if bbox and isinstance(bbox, list) and len(bbox) > 0:
            page_info = bbox[0]
            if isinstance(page_info, dict):
                page_id = page_info.get('page_id')
                if page_id is not None:
                    if page_id not in page_ids:
                        page_ids[page_id] = []
                    page_ids[page_id].append(i)

print("Page IDs found:", sorted(page_ids.keys()))
print()

# Find which page_id corresponds to page 5
# Page 5 has page_number element at index 137
for i, el in enumerate(elements):
    if isinstance(el, dict) and el.get('content') == '5' and el.get('type') == 'page_number':
        bbox = el.get('bbox', [])
        if bbox and isinstance(bbox, list) and len(bbox) > 0:
            page_info = bbox[0]
            if isinstance(page_info, dict):
                page_id = page_info.get('page_id')
                print(f"Page 5 has page_id: {page_id}")
